import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CkKL3Me7.js";const u=JSON.parse('{"title":"Projects & Types","description":"","frontmatter":{},"headers":[],"relativePath":"reference/concepts/projects.md","filePath":"reference/concepts/projects.md"}'),s={name:"reference/concepts/projects.md"};function n(i,e,c,l,d,p){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="projects-types" tabindex="-1">Projects &amp; Types <a class="header-anchor" href="#projects-types" aria-label="Permalink to &quot;Projects &amp; Types&quot;">​</a></h1><p>Every piece of work in VERA lives inside a project. A project has a type, a client, and a budget. The type determines how VERA calculates revenue.</p><hr><h2 id="project-types" tabindex="-1">Project types <a class="header-anchor" href="#project-types" aria-label="Permalink to &quot;Project types&quot;">​</a></h2><p>VERA supports five project types. <strong>The type must always be specified when creating a project — VERA will never assume a default.</strong></p><h3 id="retainer" tabindex="-1">Retainer <a class="header-anchor" href="#retainer" aria-label="Permalink to &quot;Retainer&quot;">​</a></h3><p>The client pays a fixed monthly fee for a set number of hours.</p><ul><li><strong>Budget</strong>: annual hours (e.g. 480 h/yr = 40 h/month)</li><li><strong>Revenue</strong>: fixed monthly fee (not calculated per-entry)</li><li><strong>Billing model</strong>: burn rate — VERA tracks monthly pace and flags over/underspend</li><li><strong>Work gate</strong>: no hard stop; burn rate alerts warn when pacing over budget</li><li><strong>Use case</strong>: ongoing agency relationships with a monthly scope</li></ul><blockquote><p>&quot;Create project Nike Ongoing as Retainer with 480 hours per year&quot;</p></blockquote><p>See <a href="/vera-docs/reference/concepts/retainers.html">Retainers</a> for burn rate details.</p><hr><h3 id="t-m-time-materials" tabindex="-1">T&amp;M (Time &amp; Materials) <a class="header-anchor" href="#t-m-time-materials" aria-label="Permalink to &quot;T&amp;M (Time &amp; Materials)&quot;">​</a></h3><p>Bill as you go. Revenue is calculated from logged hours.</p><ul><li><strong>Budget</strong>: total project hours</li><li><strong>Revenue</strong>: <code>hours_logged × billing_rate</code></li><li><strong>Billing model</strong>: per-entry accrual</li><li><strong>Work gate</strong>: stop work when <code>hours_budget</code> is exhausted</li><li><strong>Use case</strong>: open-scope work where effort is unpredictable</li></ul><blockquote><p>&quot;Create project Nike Campaign as T&amp;M&quot;</p></blockquote><hr><h3 id="fixed-price" tabindex="-1">Fixed Price <a class="header-anchor" href="#fixed-price" aria-label="Permalink to &quot;Fixed Price&quot;">​</a></h3><p>A flat contract for a defined scope. Revenue accrues as work is completed.</p><ul><li><strong>Budget</strong>: total project hours (the effort estimate)</li><li><strong>Contract value</strong>: the agreed price in dollars</li><li><strong>Revenue</strong>: <code>(hours_logged ÷ hours_budget) × contract_value</code> — capped at 100%</li><li><strong>Billing model</strong>: percentage-of-completion</li><li><strong>Work gate</strong>: stop work when <code>hours_budget</code> is exhausted</li><li><strong>Use case</strong>: scoped deliverables with a negotiated price</li></ul><blockquote><p>&quot;Create project Nike Rebrand as Fixed Price for $50,000 with 200 hour budget&quot;</p></blockquote><hr><h3 id="pro-bono" tabindex="-1">Pro Bono <a class="header-anchor" href="#pro-bono" aria-label="Permalink to &quot;Pro Bono&quot;">​</a></h3><p>Free work. Hours are tracked but no revenue is recognised.</p><ul><li><strong>Budget</strong>: total project hours (optional)</li><li><strong>Revenue</strong>: always $0</li><li><strong>Billing model</strong>: none</li><li><strong>Use case</strong>: charity work, community projects, internal initiatives</li></ul><blockquote><p>&quot;Create project Community Website as Pro Bono&quot;</p></blockquote><hr><h3 id="agile" tabindex="-1">Agile <a class="header-anchor" href="#agile" aria-label="Permalink to &quot;Agile&quot;">​</a></h3><p>Sprint-based work. The parent project is a container; each sprint is its own Fixed-Price-style billing unit.</p><ul><li><strong>Parent project</strong>: no contract value or budget — it&#39;s just a named container</li><li><strong>Sprints</strong>: each sprint has its own <code>contract_value</code> and <code>hours_budget</code></li><li><strong>Revenue per sprint</strong>: <code>(hours_logged ÷ hours_budget) × contract_value</code> when status = <code>active</code></li><li><strong>Sprint statuses</strong>: <code>planned</code> = $0 revenue | <code>active</code> = revenue accrues</li><li><strong>Work gate</strong>: stop work when the sprint&#39;s <code>hours_budget</code> is exhausted; raise a new sprint for additional scope</li><li><strong>Use case</strong>: iterative delivery where each sprint is separately contracted</li></ul><blockquote><p>&quot;Create project Acme App as Agile&quot; → then offer Sprint 1</p></blockquote><p>See <a href="/vera-docs/reference/concepts/sprints.html">Agile &amp; Sprints</a>.</p><hr><h2 id="project-fields" tabindex="-1">Project fields <a class="header-anchor" href="#project-fields" aria-label="Permalink to &quot;Project fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Who sets it</th></tr></thead><tbody><tr><td><code>name</code></td><td>Project name, unique per tenant</td><td>Owner</td></tr><tr><td><code>client</code></td><td>The client this project belongs to</td><td>Owner</td></tr><tr><td><code>type</code></td><td>One of the five types above</td><td>Owner</td></tr><tr><td><code>budget_hours</code></td><td>Total hours cap (or monthly for Retainer)</td><td>Owner via <code>set_project_budget</code></td></tr><tr><td><code>contract_value</code></td><td>Dollar amount (Fixed Price &amp; Agile sprints)</td><td>Owner</td></tr><tr><td><code>billing_rate</code></td><td>Hourly rate billed to client</td><td>Owner (in Projects Master)</td></tr><tr><td><code>is_billable</code></td><td>Whether hours generate revenue</td><td>Auto: false for Pro Bono, true otherwise</td></tr><tr><td><code>alert_threshold</code></td><td>% budget used before warning fires (default 80%)</td><td>Owner/Manager</td></tr><tr><td><code>deadline</code></td><td>Target delivery date</td><td>Owner via <code>set_project_deadline</code></td></tr><tr><td><code>pm_user_id</code></td><td>Assigned project manager</td><td>Owner via <code>assign_pm</code></td></tr><tr><td><code>project_category</code></td><td><code>client</code>, <code>internal</code>, <code>pto</code>, <code>sick</code>, <code>leave</code>, <code>time_off</code></td><td>Auto-set</td></tr><tr><td><code>status</code></td><td><code>active</code> or <code>inactive</code></td><td>Owner</td></tr></tbody></table><hr><h2 id="project-category-vs-type" tabindex="-1">Project category vs. type <a class="header-anchor" href="#project-category-vs-type" aria-label="Permalink to &quot;Project category vs. type&quot;">​</a></h2><p>These are two separate fields:</p><ul><li><strong>Type</strong> (<code>T&amp;M</code>, <code>Fixed Price</code>, etc.) governs <strong>billing and revenue recognition</strong></li><li><strong>Category</strong> (<code>client</code>, <code>internal</code>, <code>time_off</code>, etc.) governs <strong>how VERA treats the project in reports and queries</strong></li></ul><p>Internal projects (training, admin, hiring) should use the &quot;Internal&quot; client and <code>project_category = &quot;internal&quot;</code>. They still have a type (usually T&amp;M or Pro Bono) for tracking purposes.</p><p>Protected projects (Out of Office, Sick, Leave) are auto-created with special categories and cannot be deleted.</p><hr><h2 id="the-two-tier-budget-model" tabindex="-1">The two-tier budget model <a class="header-anchor" href="#the-two-tier-budget-model" aria-label="Permalink to &quot;The two-tier budget model&quot;">​</a></h2><p>There are two completely separate budget concepts. Do not confuse them.</p><p><strong>Tier 1 — Project total</strong>: <code>budget_hours</code> in the Projects sheet. This is the sold or contracted hours for the whole project. Set by Owner only via <code>set_project_budget</code>. Think of it as the pie.</p><p><strong>Tier 2 — Envelopes</strong>: rows in the Budgets sheet (<code>07. Budgets</code>). This is how Managers slice the pie — each team member gets a per-person envelope. The sum of all envelopes should not exceed Tier 1.</p><blockquote><p>A Manager asking &quot;how do I set the budget?&quot; wants to distribute hours to their team (Tier 2). The overall budget is set by the Owner (Tier 1) and is not the Manager&#39;s to change.</p></blockquote><p>See <a href="/vera-docs/reference/concepts/allocations.html">Envelopes</a> for the full picture.</p><hr><h2 id="project-lifecycle" tabindex="-1">Project lifecycle <a class="header-anchor" href="#project-lifecycle" aria-label="Permalink to &quot;Project lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Created → Budget set → PM assigned → Tasks enabled → Envelopes created</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                               Team logs time → Alerts fire if approaching budget</span></span>
<span class="line"><span>                                          ↓</span></span>
<span class="line"><span>                                    Completed / Inactive</span></span></code></pre></div><p>No formal state machine enforces this flow — VERA relies on the configured <code>status</code> field and the business rules in its system prompt.</p><hr><h2 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h2><p>Every project belongs to a client. If a client doesn&#39;t exist yet, VERA creates it automatically when a project is created.</p><p>Internal or overhead work belongs to the built-in &quot;Internal&quot; client. VERA creates &quot;Internal&quot; automatically when the first internal project is provisioned.</p><p>Financial rollups are client-aware: <code>get_client_summary</code> aggregates hours, budget, and spend across all of a client&#39;s projects.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="/vera-docs/blog/07-retainers-are-weird.html">Retainers Without Timely Data Are Just Guesses</a> — how the retainer model forces timeliness as a first-class constraint</li><li><a href="/vera-docs/blog/14-agile-as-billing-model.html">Agile as a Billing Model</a> — why sprint-based revenue recognition made logging accuracy non-negotiable</li></ul>`,58)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
